pragma solidity ^0.8.0;

contract HexStringStorage {
    bytes[] public s;

    address public admin;

    event HexStringModified(uint256 index, string oldValue, string newValue);

    event AdminChanged(address indexed oldAdmin, address indexed newAdmin);

    constructor() {
        admin = msg.sender;
        s = new bytes[](10);
    }

    
    function setHexString(uint256 index, string memory _hexString) public onlyAdmin {
        require(index < s.length, "Index out of bounds");
        string memory oldValue = string(s[index]);
        s[index] = bytes(_hexString);
        emit HexStringModified(index, oldValue, _hexString);
    }

    function getHexString(uint256 index) public view returns (string memory) {
        require(index < s.length, "Index out of bounds");
        return string(s[index]);
    }

    function setAdmin(address _newAdmin) public onlyAdmin {
        emit AdminChanged(admin, _newAdmin);
        admin = _newAdmin;
    }

    modifier onlyAdmin() {
        require(msg.sender == admin, "Only admin can call this function");
        _;
    }
}
